CREATE TABLE `workflow_builds` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` binary(16) DEFAULT NULL,
  `queued_at` datetime(6) DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `completed_at` datetime(6) DEFAULT NULL,
  `repository_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `repository_next_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `commit_sha` varchar(40) COLLATE utf8mb4_general_ci NOT NULL,
  `workflow_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Workflow identifier',
  `check_suite_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `check_suite_next_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `request_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '',
  `state` int NOT NULL DEFAULT '0' COMMENT 'See WorkflowState for values',
  `workflow_file_path` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '.github/main.workflow',
  `reporting_metadata` json DEFAULT NULL COMMENT 'See WorkflowMetadata for values',
  `token_permissions` json DEFAULT NULL COMMENT 'The serialized token.PermissionSettings for run',
  `workflow_run_id` bigint unsigned DEFAULT '0' COMMENT 'The workflow run database ID',
  `workflow_run_number` bigint unsigned DEFAULT '0' COMMENT 'The workflow run number',
  `event` varchar(40) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'The GitHub event that kicked off a build',
  `event_time` datetime(6) DEFAULT NULL,
  `checkout_sha` varchar(40) COLLATE utf8mb4_general_ci NOT NULL,
  `checkout_ref` varbinary(1024) NOT NULL,
  `event_ref` varbinary(1024) NOT NULL DEFAULT '',
  `rerun` tinyint(1) DEFAULT '0',
  `webhook_delivery_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `executing_actor_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `executing_actor_next_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `imposer_repository_id` bigint unsigned DEFAULT '0' COMMENT 'The source repository of a required workflow. This will be 0 for non required workflows',
  `github_tenant_id` bigint unsigned DEFAULT NULL COMMENT 'The github tenant id (business id) owning that repository that triggered the workflow. This value will always be NULL in non multi-tenant environments',
  `backend` tinyint NOT NULL DEFAULT '0' COMMENT 'The backend service that is orchestrating this workflow',
  `workflow_sha` varchar(40) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'The sha of the workflow file',
  `pinned_workflow_ref` varbinary(1024) NOT NULL DEFAULT '' COMMENT 'The ref of the required workflow file if it is pinned to a ref',
  PRIMARY KEY (`id`),
  UNIQUE KEY `by_check_suite_id` (`check_suite_id`),
  UNIQUE KEY `by_uuid` (`uuid`),
  UNIQUE KEY `by_check_suite_next_id` (`check_suite_next_id`),
  UNIQUE KEY `by_delivery_id_workflow_file_path_event_imposer_sha_ref` (`webhook_delivery_id`,`workflow_file_path`,`event`,`imposer_repository_id`,`workflow_sha`,`pinned_workflow_ref`),
  KEY `by_created_at` (`created_at`),
  KEY `by_repository_next_id` (`repository_next_id`),
  KEY `by_executing_actor_next_id_state_queued_at` (`executing_actor_next_id`,`state`,`queued_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
